package com.naveenans.olabatteryalert;
import android.app.*; import android.appwidget.*; import android.content.*; import android.os.IBinder;
public class WidgetMonitorService extends Service { private static final int HOST_ID=41041; private BatteryWidgetHost host; @Override public void onCreate(){super.onCreate(); AlertEngine.channels(this); startForeground(4104,new Notification.Builder(this,AlertEngine.MONITOR).setSmallIcon(android.R.drawable.ic_lock_idle_charging).setContentTitle("Ola Battery Alert active").setContentText("Monitoring selected Ola widget").setOngoing(true).build()); int id=getSharedPreferences("prefs",0).getInt("widget_id",AppWidgetManager.INVALID_APPWIDGET_ID); if(id!=AppWidgetManager.INVALID_APPWIDGET_ID){host=new BatteryWidgetHost(this,HOST_ID); host.startListening(); AppWidgetProviderInfo info=AppWidgetManager.getInstance(this).getAppWidgetInfo(id); if(info!=null){BatteryWidgetHostView v=(BatteryWidgetHostView)host.createView(this,id,info); v.setListener(p->{if(p!=null)AlertEngine.process(this,p,"Ola widget");}); v.postDelayed(()->{Integer p=BatteryParser.fromView(v); if(p!=null)AlertEngine.process(this,p,"Ola widget");},1200);}}} @Override public void onDestroy(){if(host!=null)host.stopListening(); super.onDestroy();} @Override public IBinder onBind(Intent i){return null;} }
